  def encode_gatherer_code(_), do: {:error, "Unexpected type when encoding TopLevel.gatherer_code"}

  def decode_magic_cards_info_code(value) when is_binary(value), do: value
  def decode_magic_cards_info_code(_), do: {:error, "Unexpected type when decoding TopLevel.magic_cards_info_code"}

  def encode_magic_cards_info_code(value) when is_binary(value), do: value
  def encode_magic_cards_info_code(_), do: {:error, "Unexpected type when encoding TopLevel.magic_cards_info_code"}

  def decode_mkm_id(value) when is_integer(value), do: value
  def decode_mkm_id(_), do: {:error, "Unexpected type when decoding TopLevel.mkm_id"}

  def encode_mkm_id(value) when is_integer(value), do: value
  def encode_mkm_id(_), do: {:error, "Unexpected type when encoding TopLevel.mkm_id"}

  def decode_mkm_name(value) when is_binary(value), do: value
  def decode_mkm_name(_), do: {:error, "Unexpected type when decoding TopLevel.mkm_name"}

  def encode_mkm_name(value) when is_binary(value), do: value
  def encode_mkm_name(_), do: {:error, "Unexpected type when encoding TopLevel.mkm_name"}

  def decode_name(value) when is_binary(value), do: value
  def decode_name(_), do: {:error, "Unexpected type when decoding TopLevel.name"}

  def encode_name(value) when is_binary(value), do: value
  def encode_name(_), do: {:error, "Unexpected type when encoding TopLevel.name"}

  def decode_release_date(value) when is_binary(value), do: value
  def decode_release_date(_), do: {:error, "Unexpected type when decoding TopLevel.release_date"}

  def encode_release_date(value) when is_binary(value), do: value
  def encode_release_date(_), do: {:error, "Unexpected type when encoding TopLevel.release_date"}

  def decode_type(value) when is_binary(value), do: value
  def decode_type(_), do: {:error, "Unexpected type when decoding TopLevel.type"}

  def encode_type(value) when is_binary(value), do: value
  def encode_type(_), do: {:error, "Unexpected type when encoding TopLevel.type"}

  def from_map(m) do
    %TopLevel{
      booster: Enum.map(m["booster"], &Booster.decode/1),
      border: decode_border(m["border"]),
      cards: Enum.map(m["cards"], &Card.from_map/1),
      code: decode_code(m["code"]),
      gatherer_code: decode_gatherer_code(m["gathererCode"]),
      magic_cards_info_code: decode_magic_cards_info_code(m["magicCardsInfoCode"]),
      mkm_id: decode_mkm_id(m["mkm_id"]),
      mkm_name: decode_mkm_name(m["mkm_name"]),
      name: decode_name(m["name"]),
      release_date: decode_release_date(m["releaseDate"]),
      type: decode_type(m["type"]),
    }
  end

  def from_json(json) do
    json
          |> Jason.decode!()
          |> from_map()
  end

  def to_map(struct) do
    %{
      "booster" => struct.booster && Enum.map(struct.booster, &Booster.encode/1),
      "border" => struct.border,
      "cards" => struct.cards && Enum.map(struct.cards, &Card.to_map/1),
      "code" => struct.code,
      "gathererCode" => struct.gatherer_code,
      "magicCardsInfoCode" => struct.magic_cards_info_code,
      "mkm_id" => struct.mkm_id,
      "mkm_name" => struct.mkm_name,
      "name" => struct.name,
      "releaseDate" => struct.release_date,
      "type" => struct.type,
    }
  end

  def to_json(struct) do
    struct
          |> to_map()
          |> Jason.encode!()
  end
end
